import { useState, type FormEvent } from 'react';
import { Button, Input, Select, Switch } from '@jinx-ui/react';

export type ProfileLanguage = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: ProfileLanguage;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS: ReadonlyArray<{ value: ProfileLanguage; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<ProfileLanguage>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );

  const trimmedName = name.trim();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (trimmedName.length === 0) return;
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <form
      className="jx-card jx-stack"
      style={{ gap: 'var(--jx-space-4)', padding: 'var(--jx-space-5)' }}
      onSubmit={handleSubmit}
      aria-labelledby="profile-settings-title"
    >
      <h2 id="profile-settings-title" className="jx-heading">
        Настройки профиля
      </h2>

      <div className="jx-field">
        <label className="jx-label" htmlFor="profile-name">
          Имя
        </label>
        <Input
          id="profile-name"
          name="name"
          value={name}
          autoComplete="name"
          placeholder="Введите имя"
          onChange={(event) => setName(event.target.value)}
        />
      </div>

      <div className="jx-field">
        <label className="jx-label" htmlFor="profile-language">
          Язык интерфейса
        </label>
        <Select
          id="profile-language"
          name="language"
          value={language}
          options={LANGUAGE_OPTIONS}
          onChange={(value: string) => setLanguage(value as ProfileLanguage)}
        />
      </div>

      <div
        className="jx-field jx-row"
        style={{ alignItems: 'center', gap: 'var(--jx-space-3)' }}
      >
        <Switch
          id="profile-email-notifications"
          name="emailNotifications"
          checked={emailNotifications}
          onChange={setEmailNotifications}
        />
        <label className="jx-label" htmlFor="profile-email-notifications">
          Уведомления на почту
        </label>
      </div>

      <div className="jx-row" style={{ justifyContent: 'flex-end' }}>
        <Button type="submit" disabled={trimmedName.length === 0}>
          Сохранить
        </Button>
      </div>
    </form>
  );
}

export default ProfileSettingsForm;

